fr:{kombi:["Ménage + RC privée pour les moins de 26 ans","Idéal pour le premier appartement ou la chambre en colocation.","dès CHF 12.–","par mois"],recht:["Protection juridique privée & circulation","De l'aide en cas de litige avec le bailleur, l'employeur ou une boutique en ligne.","3 mois offerts",""],reise:["Assurance voyage à l'année","Annulation et assistance à l'étranger, pour tous tes voyages.","dès CHF 8.–","par mois"],auto:["Assurance auto pour nouveaux conducteurs","Une prime équitable la première année après le permis.","10 % de rabais","la première année"],partner:["Votre offre ici","Assureurs et banques peuvent louer cet espace pour leurs offres.","",""]},
